    def forward(self, x):
        champ_indices = x[:, :10].long()
        numerical_values = x[:, 10:].float()
        normalized = (numerical_values - self.means) / self.std
        embeddings = self.embed(champ_indices)

        x = torch.cat([normalized, embeddings.reshape(x.size(0), -1)], dim=1)

        return self.stack(x)
